    centerActiveTab();
  }
  matchMedia("(max-width: 760px)").addEventListener("change", checkMobileUI);
  matchMedia("(pointer: coarse)").addEventListener("change", checkMobileUI);
  window.addEventListener("resize", checkMobileUI);

  /* Инициализация */
  render();
  centerActiveTab();
})();
```

