VOID = {'img','br','input','hr','meta','link'}
class P(HTMLParser):
    def __init__(self):
        super().__init__()
        self.stack=[]; self.bad=[]; self.depth=0
    def handle_starttag(self, tag, attrs):
        if tag in VOID: return
        self.stack.append(tag); self.depth+=1
    def handle_endtag(self, tag):
        if not self.stack: self.bad.append('end without open: '+tag); return
        if tag not in self.stack: self.bad.append('unmatched end: '+tag); return
        # find matching
        if self.stack[-1]==tag: self.stack.pop()
        else: self.bad.append('mismatch (expected %s got %s)'%(self.stack[-1], tag)); self.stack.pop()
    def handle_startendtag(self, tag, attrs): pass
